pub fn intersperse(numbers: &[i32], delim: i32) -> Vec<i32> {
    let n = numbers.len();
    if n == 0 {
        return Vec::new();
    }

    // For n > 0, result length must be exactly 2n - 1.
    let mut res = Vec::with_capacity(2 * n - 1);

    for (i, &x) in numbers.iter().enumerate() {
        if i != 0 {
            res.push(delim);
        }
        res.push(x);
    }

    res
}